-- C-04 sales quotes/orders/deliveries. No historical document or stock backfill.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema sales_workflow_private;revoke all on schema sales_workflow_private from public,anon,authenticated,service_role;grant usage on schema sales_workflow_private to authenticated;
create function sales_workflow_private.resource(k text) returns text language plpgsql immutable set search_path=pg_catalog as $$begin if k is null or k not in('QUOTE','ORDER','DELIVERY') then raise exception using errcode='22023',message='Tipo de venta inválido.';end if;return case k when 'QUOTE' then 'sales:quotations' when 'ORDER' then 'sales:sales-orders' else 'sales:deliveries' end;end$$;
create function sales_workflow_private.access(k text,a text) returns bigint language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select asset_posting_private.access(sales_workflow_private.resource(k),a)$$;
create function sales_workflow_private.allowed(k text,a text) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if k is null or k not in('QUOTE','ORDER','DELIVERY') then return false;end if;return asset_posting_private.allowed(sales_workflow_private.resource(k),a);end$$;
create function sales_workflow_private.visible(id bigint) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from public.sales_document where document_id=id and subsidiary_id=asset_posting_private.identity() and sales_workflow_private.allowed(document_type,'view'))$$;
create function sales_workflow_private.header(id bigint,a text) returns public.sales_document language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.sales_document;begin select * into d from public.sales_document where document_id=id and subsidiary_id=asset_posting_private.identity();if not found then raise exception using errcode='42501',message='Documento no disponible.';end if;perform sales_workflow_private.access(d.document_type,a);return d;end$$;
alter table public.sales_document_line add column source_line_id bigint references public.sales_document_line(line_id) on delete restrict;
alter table public.stock_movements add column sales_delivery_line_id bigint references public.sales_document_line(line_id) on delete restrict;
create unique index stock_sales_delivery_line_unique on public.stock_movements(sales_delivery_line_id) where sales_delivery_line_id is not null;
create unique index invoice_sales_delivery_unique on public.invoice(sales_delivery_document_id) where sales_delivery_document_id is not null;
alter function public.save_sales_document(jsonb,bigint) set schema sales_workflow_private;
alter function public.delete_sales_document(bigint) set schema sales_workflow_private;
alter function public.sales_document_detail(bigint) set schema sales_workflow_private;
alter function public.sales_document_report(jsonb) set schema sales_workflow_private;
alter function public.sales_workflow_options() set schema sales_workflow_private;
-- Retain original calculations; bind each newly-created stock movement to its line.
do $$declare body text;begin body:=pg_get_functiondef('sales_workflow_private.save_sales_document(jsonb,bigint)'::regprocedure);
 body:=replace(body,'prod products%rowtype;','prod products%rowtype;delivery_line bigint;');
 if position($needle$::bigint);if kind='DELIVERY'$needle$ in body)=0 then raise exception 'Unexpected sales line writer';end if;
 body:=replace(body,$needle$::bigint);if kind='DELIVERY'$needle$,$replacement$::bigint) returning line_id into delivery_line;if kind='DELIVERY'$replacement$);
 body:=replace(body,'movement_type,unit_cost)values','movement_type,unit_cost,sales_delivery_line_id)values');
 body:=replace(body,'coalesce(prod.purchase_cost,0));','coalesce(prod.purchase_cost,0),delivery_line);');execute body;
end$$;
create function sales_workflow_private.lock_header(id bigint) returns public.sales_document language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.sales_document;sid bigint:=asset_posting_private.identity();begin
 select * into d from public.sales_document where document_id=id and subsidiary_id=sid;if not found then raise exception using errcode='42501',message='Documento no disponible.';end if;
 perform 1 from public."transaction" where transaction_id=d.transaction_id for update;select * into d from public.sales_document where document_id=id and subsidiary_id=sid for update;
 if not asset_posting_private.finite(d.total_amount) or d.total_amount<=0 or not asset_posting_private.finite(d.exchange_rate) or d.exchange_rate<=0 or not exists(select 1 from public."transaction" t join public.transaction_types tt using(transaction_type_id) where t.transaction_id=d.transaction_id and t.subsidiary_id=sid and tt.abbreviation=case d.document_type when 'QUOTE' then 'COT_VEN' when 'ORDER' then 'PED_VEN' else 'DES_INV' end and t.currency_id=d.currency_id and t.exchange_rate=d.exchange_rate and t.fiscal_period_id=d.fiscal_period_id and t.tran_date=d.document_date and t.customer_id=d.customer_id and t.total_amount=d.total_amount and t.tran_number=d.document_number)
 then raise exception using errcode='55000',message='El origen del documento requiere revisión.';end if;return d;end$$;
create function sales_workflow_private.editable(d public.sales_document) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin
 if d.document_type='DELIVERY' or d.status not in('BORRADOR','RECHAZADO') or exists(select 1 from public.sales_document where source_document_id=d.document_id) or exists(select 1 from public.invoice where sales_delivery_document_id=d.document_id or so_id=d.document_id) or exists(select 1 from public.wf_instances where entity_type='SALES_ORDER' and entity_id=d.document_id and status not in('BORRADOR','RECHAZADO')) or exists(select 1 from public.stock_movements where transaction_id=d.transaction_id)
 then raise exception using errcode='55000',message='El documento tiene aprobación, movimientos o procesos posteriores.';end if;
 perform sales_invoice_private.period(d.fiscal_period_id,d.document_date);end$$;
create function sales_workflow_private.source(id bigint,k text) returns public.sales_document language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.sales_document;begin
 if k='INVOICE' then perform sales_invoice_private.access('create');else if not(sales_workflow_private.allowed(k,'create') or sales_workflow_private.allowed(k,'edit')) then raise exception using errcode='42501',message='No puede utilizar este origen.';end if;end if;
 d:=sales_workflow_private.lock_header(id);
 if d.document_type is distinct from(case k when 'ORDER' then 'QUOTE' when 'DELIVERY' then 'ORDER' when 'INVOICE' then 'DELIVERY' end) or d.status in('CANCELADO','CERRADO') or(k='DELIVERY' and d.status<>'APROBADO') or(k='INVOICE' and exists(select 1 from public.invoice where sales_delivery_document_id=id)) then raise exception using errcode='55000',message='El documento origen no está disponible para esta transición.';end if;return d;end$$;
create function sales_workflow_private.prepare(p jsonb,id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare k text:=p->>'type';sid bigint:=sales_workflow_private.access(k,case when id is null then 'create' else 'edit' end);d public.sales_document;origin public.sales_document;source_line public.sales_document_line;ln jsonb;lines jsonb:='[]';prod public.products;field text;qty numeric;price numeric;rate numeric;tax_account bigint;source_id bigint:=nullif(p->>'source_id','')::bigint;idx bigint:=0;used numeric;begin
 if jsonb_typeof(p) is distinct from 'object' or jsonb_typeof(p->'lines') is distinct from 'array' or jsonb_array_length(p->'lines') not between 1 and 500 then raise exception using errcode='22023',message='Seleccione entre 1 y 500 líneas.';end if;
 if p ?| array['subsidiary_id','transaction_id','journal_id','document_number','document_id','created_by','total_amount'] then raise exception using errcode='42501',message='No puede sustituir el origen del documento.';end if;
 if k='ORDER' and coalesce(nullif(p->>'status',''),'BORRADOR')<>'BORRADOR' or k='DELIVERY' and coalesce(nullif(p->>'status',''),'BORRADOR')<>'BORRADOR' or k='QUOTE' and coalesce(nullif(p->>'status',''),'BORRADOR') not in('BORRADOR','APROBADO','CANCELADO','CERRADO') then raise exception using errcode='42501',message='El estado requiere el proceso autorizado.';end if;
 if k='QUOTE' and source_id is not null or k='DELIVERY' and source_id is null then raise exception using errcode='22023',message='Origen inválido para este documento.';end if;
 if source_id is not null then origin:=sales_workflow_private.source(source_id,k);end if;
 if id is not null then d:=sales_workflow_private.lock_header(id);if d.document_type is distinct from k then raise exception using errcode='42501',message='No puede cambiar el tipo de documento.';end if;perform sales_workflow_private.editable(d);if d.source_document_id is distinct from source_id then raise exception using errcode='42501',message='El documento conserva su origen.';end if;end if;
 perform sales_invoice_private.period((p->>'period_id')::bigint,(p->>'date')::date);
 if not exists(select 1 from public.customers c join public.entity_subsidiaries e using(customer_id) where c.customer_id=(p->>'customer_id')::bigint and e.subsidiary_id=sid and not coalesce((to_jsonb(c)->>'is_inactive')::boolean,false)) then raise exception using errcode='42501',message='Cliente no habilitado.';end if;
 if not exists(select 1 from public.subsidiary_currencies where subsidiary_id=sid and currency_id=(p->>'currency_id')::bigint) then raise exception using errcode='42501',message='Moneda no habilitada.';end if;
 if nullif(p->>'location_id','') is not null and not inventory_balance_private.location((p->>'location_id')::bigint) or k='DELIVERY' and nullif(p->>'location_id','') is null then raise exception using errcode='42501',message='Ubicación no disponible para el despacho.';end if;
 if nullif(p->>'payment_term_id','') is null or not exists(select 1 from public.payment_terms where term_id=(p->>'payment_term_id')::bigint) then raise exception using errcode='22023',message='Término de pago requerido.';end if;
 if not asset_posting_private.finite((p->>'rate')::numeric) or(p->>'rate')::numeric<=0 then raise exception using errcode='22023',message='Tipo de cambio inválido.';end if;
 if nullif(p->>'valid_until','')::date<(p->>'date')::date then raise exception using errcode='22023',message='Vigencia inválida.';end if;
 if origin.document_id is not null and(origin.customer_id is distinct from(p->>'customer_id')::bigint or origin.currency_id is distinct from(p->>'currency_id')::bigint or origin.document_date>(p->>'date')::date or k='ORDER' and origin.valid_until<(p->>'date')::date or k='DELIVERY' and origin.location_id is not null and origin.location_id is distinct from nullif(p->>'location_id','')::bigint) then raise exception using errcode='42501',message='El origen no corresponde al cliente, moneda, ubicación o fecha.';end if;
 p:=p||jsonb_build_object('rate',sales_invoice_private.sales_invoice_official_exchange_rate((p->>'currency_id')::bigint,(p->>'date')::date,sid));
 for ln in select value from jsonb_array_elements(p->'lines') loop
 if jsonb_typeof(ln) is distinct from 'object' then raise exception using errcode='22023',message='Línea inválida.';end if;
 foreach field in array array['quantity','unit_price','amount','tax_rate','tax_amount','gross_amount'] loop if ln?field and not asset_posting_private.finite((ln->>field)::numeric) then raise exception using errcode='22023',message='Los importes deben ser finitos.';end if;end loop;
 qty:=(ln->>'quantity')::numeric;price:=(ln->>'unit_price')::numeric;if not asset_posting_private.finite(qty) or not asset_posting_private.finite(price) or qty<=0 or price<0 then raise exception using errcode='22023',message='Cantidad positiva y precio no negativo requeridos.';end if;
 select * into prod from public.products where product_id=(ln->>'product_id')::bigint and is_active and product_usage in('Venta','Ambas') and exists(select 1 from public.product_subsidiaries ps where ps.product_id=products.product_id and ps.subsidiary_id=sid and ps.is_active);
 if not found then raise exception using errcode='42501',message='Producto no habilitado para ventas.';end if;if k='DELIVERY' and(not asset_posting_private.finite(coalesce(prod.purchase_cost,0)) or coalesce(prod.purchase_cost,0)<0) then raise exception using errcode='55000',message='Costo de producto inválido para el despacho.';end if;
 perform asset_posting_private.account(prod.sales_account_id);if not exists(select 1 from public.chart_accounts where account_id=prod.sales_account_id and category='Ingreso') then raise exception using errcode='22023',message='El producto requiere cuenta de Ingreso.';end if;
 if ln?'account_id' and(ln->>'account_id')::bigint is distinct from prod.sales_account_id then raise exception using errcode='42501',message='No puede sustituir la cuenta del producto.';end if;
 perform asset_posting_private.dimensions(nullif(ln->>'department_id','')::bigint,nullif(ln->>'cost_center_id','')::bigint,nullif(ln->>'class_id','')::bigint);
 if nullif(ln->>'related_company_id','') is not null and not exists(select 1 from public.related_companies r join public.related_company_subsidiaries s using(related_company_id) where r.related_company_id=(ln->>'related_company_id')::bigint and s.subsidiary_id=sid and not r.is_inactive) then raise exception using errcode='42501',message='Compañía relacionada fuera del alcance.';end if;
 rate:=0;tax_account:=null;
 if nullif(ln->>'tax_code_id','') is not null then select tc.rate_percentage,tt.liability_account_id into rate,tax_account from public.tax_codes tc join public.tax_types tt using(tax_type_id) where tc.tax_code_id=(ln->>'tax_code_id')::bigint and not tc.is_withholding and tt.applies_to in('Ventas','Ambos') and exists(select 1 from public.tax_code_subsidiaries s where s.tax_code_id=tc.tax_code_id and s.subsidiary_id=sid);if not found then raise exception using errcode='42501',message='Impuesto de venta no autorizado.';end if;end if;
 if not asset_posting_private.finite(rate) or rate not between 0 and 100 or ln?'tax_rate' and(ln->>'tax_rate')::numeric is distinct from rate then raise exception using errcode='22023',message='La tasa debe coincidir con el impuesto configurado.';end if;
 if rate>0 then perform asset_posting_private.account(tax_account);end if;
 lines:=lines||jsonb_build_array(ln||jsonb_build_object('tax_rate',rate,'amount',round(qty*price,6),'tax_amount',round(round(qty*price,6)*rate/100,6),'gross_amount',round(qty*price,6)+round(round(qty*price,6)*rate/100,6)));
 end loop;
 if (select sum((x->>'gross_amount')::numeric) from jsonb_array_elements(lines)x)<=0 then raise exception using errcode='22023',message='La factura requiere total positivo.';end if;

 -- Source quantities and approved commercial terms are authoritative.
 for ln in select value from jsonb_array_elements(lines) loop idx:=idx+1;
 if source_id is not null then
 select * into source_line from public.sales_document_line where document_id=source_id and line_id=coalesce(nullif(ln->>'source_line_id','')::bigint,(select line_id from public.sales_document_line where document_id=source_id and line_number=idx));
 if not found or not asset_posting_private.finite(source_line.quantity) or source_line.quantity<=0 or source_line.product_id is distinct from(ln->>'product_id')::bigint or source_line.account_id is distinct from(select sales_account_id from public.products where product_id=source_line.product_id) or source_line.unit_price is distinct from(ln->>'unit_price')::numeric or source_line.tax_code_id is distinct from nullif(ln->>'tax_code_id','')::bigint or source_line.tax_rate is distinct from(ln->>'tax_rate')::numeric or source_line.department_id is distinct from nullif(ln->>'department_id','')::bigint or source_line.cost_center_id is distinct from nullif(ln->>'cost_center_id','')::bigint or source_line.class_id is distinct from nullif(ln->>'class_id','')::bigint or source_line.related_company_id is distinct from nullif(ln->>'related_company_id','')::bigint then raise exception using errcode='42501',message='La línea no conserva los términos de su origen.';end if;
 select coalesce(sum(l.quantity),0) into used from public.sales_document child join public.sales_document_line l on l.document_id=child.document_id where child.source_document_id=source_id and child.document_type=k and child.status<>'CANCELADO' and child.document_id is distinct from id and(l.source_line_id=source_line.line_id or(l.source_line_id is null and l.line_number=source_line.line_number));
 if (ln->>'quantity')::numeric+used>source_line.quantity+.000001 then raise exception using errcode='55000',message='La cantidad supera el saldo del origen.';end if;
 lines:=jsonb_set(lines,array[(idx-1)::text],ln||jsonb_build_object('source_line_id',source_line.line_id));
 elsif nullif(ln->>'source_line_id','') is not null then raise exception using errcode='42501',message='Línea origen sin documento origen.';end if;
 end loop;
 if source_id is not null and(select count(*)<>count(distinct(x->>'source_line_id')::bigint) from jsonb_array_elements(lines)x) then raise exception using errcode='22023',message='No repita líneas de origen.';end if;
 return p||jsonb_build_object('lines',lines,'status',coalesce(nullif(p->>'status',''),'BORRADOR'));end$$;
create function public.save_sales_document(p_payload jsonb,p_document_id bigint default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare p jsonb;r jsonb;d public.sales_document;old_guard text:=current_setting('nexo.sales_delivery_write',true);begin
 p:=sales_workflow_private.prepare(p_payload,p_document_id);perform set_config('nexo.sales_delivery_write','true',true);r:=sales_workflow_private.save_sales_document(p,p_document_id);
 select * into d from public.sales_document where document_id=(r->>'id')::bigint;
 update public."transaction" set currency_id=d.currency_id,exchange_rate=d.exchange_rate,fiscal_period_id=d.fiscal_period_id,customer_id=d.customer_id,payment_term_id=d.payment_term_id where transaction_id=d.transaction_id;
 with supplied as(select ordinality,(value->>'source_line_id')::bigint source_line_id from jsonb_array_elements(p->'lines') with ordinality) update public.sales_document_line l set source_line_id=s.source_line_id from supplied s where l.document_id=d.document_id and l.line_number=s.ordinality;
 if d.document_type='DELIVERY' and(select count(*) from public.stock_movements where transaction_id=d.transaction_id)<>(select count(*) from public.sales_document_line where document_id=d.document_id) then raise exception using errcode='55000',message='Movimientos del despacho inconsistentes.';end if;
 perform set_config('nexo.sales_delivery_write',coalesce(old_guard,''),true);return r;end$$;
create function sales_workflow_private.stock_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare m public.stock_movements;d public.sales_document;l public.sales_document_line;begin
 if tg_op='UPDATE' and(old.sales_delivery_line_id is not null or old.movement_type='DESPACHO_VENTA' or exists(select 1 from public.sales_document where transaction_id=old.transaction_id and document_type='DELIVERY')) then raise exception using errcode='55000',message='El movimiento conserva su despacho original.';end if;
 if tg_op='DELETE' then m:=old;else m:=new;end if;select * into d from public.sales_document where transaction_id=m.transaction_id and document_type='DELIVERY';
 if m.sales_delivery_line_id is null and m.movement_type<>'DESPACHO_VENTA' and d.document_id is null then return case when tg_op='DELETE' then old else new end;end if;
 if tg_op<>'INSERT' or current_setting('nexo.sales_delivery_write',true) is distinct from 'true' or d.document_id is null then raise exception using errcode='55000',message='El movimiento del despacho conserva su historial.';end if;
 select * into l from public.sales_document_line where line_id=m.sales_delivery_line_id and document_id=d.document_id;
 if not found or m.product_id is distinct from l.product_id or m.location_id is distinct from d.location_id or m.quantity is distinct from -l.quantity or m.unit_cost is distinct from(select coalesce(purchase_cost,0) from public.products where product_id=l.product_id) or m.movement_date::date is distinct from d.document_date or m.movement_type is distinct from 'DESPACHO_VENTA' then raise exception using errcode='55000',message='Movimiento de despacho inválido.';end if;return new;end$$;
create trigger sales_delivery_stock_guard before insert or update or delete on public.stock_movements for each row execute function sales_workflow_private.stock_guard();
create function sales_workflow_private.actions(id bigint) returns jsonb language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select jsonb_build_object('canEdit',x.editable and sales_workflow_private.allowed(d.document_type,'edit'),'canDelete',x.editable and sales_workflow_private.allowed(d.document_type,'delete') and not exists(select 1 from public.wf_instances where entity_type='SALES_ORDER' and entity_id=$1),'canSubmit',x.editable and d.document_type='ORDER' and sales_workflow_private.allowed('ORDER','edit'),'canCreateNext',case d.document_type when 'QUOTE' then d.status not in('CANCELADO','CERRADO') and sales_workflow_private.allowed('ORDER','create') when 'ORDER' then d.status='APROBADO' and sales_workflow_private.allowed('DELIVERY','create') else asset_posting_private.allowed('sales:invoices','create') and not exists(select 1 from public.invoice where sales_delivery_document_id=$1) end) from public.sales_document d cross join lateral(select d.document_type<>'DELIVERY' and d.status in('BORRADOR','RECHAZADO') and not exists(select 1 from public.sales_document where source_document_id=$1) and not exists(select 1 from public.invoice where sales_delivery_document_id=$1 or so_id=$1) and not exists(select 1 from public.wf_instances where entity_type='SALES_ORDER' and entity_id=$1 and status not in('BORRADOR','RECHAZADO')) as editable)x where document_id=$1$$;
create function public.sales_document_access(p_type text) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare v boolean;c boolean;e boolean;d boolean;begin perform asset_posting_private.identity();v:=sales_workflow_private.allowed(p_type,'view');c:=sales_workflow_private.allowed(p_type,'create');e:=sales_workflow_private.allowed(p_type,'edit');d:=sales_workflow_private.allowed(p_type,'delete');if not(v or c or e or d) then raise exception using errcode='42501',message='Sin acceso a este tipo de venta.';end if;return jsonb_build_object('canView',v,'canCreate',c,'canEdit',e,'canDelete',d);end$$;
create function public.sales_document_report(p_filters jsonb) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare r jsonb;begin perform sales_workflow_private.access(p_filters->>'type','view');r:=sales_workflow_private.sales_document_report(p_filters);return r||jsonb_build_object('access',public.sales_document_access(p_filters->>'type'),'rows',(select coalesce(jsonb_agg(x||jsonb_build_object('actions',sales_workflow_private.actions((x->>'id')::bigint))),'[]') from jsonb_array_elements(r->'rows')x));end$$;
create function sales_workflow_private.detail(id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare r jsonb;sid bigint:=asset_posting_private.identity();begin
 r:=sales_workflow_private.sales_document_detail(id);if r is null then raise exception using errcode='42501',message='Documento no disponible.';end if;
 return r||jsonb_build_object('actions',sales_workflow_private.actions(id),'refs',jsonb_build_object('subsidiary',(select jsonb_build_object('id',subsidiary_id,'name',name) from public.subsidiaries where subsidiary_id=sid),'customers',(select coalesce(jsonb_agg(jsonb_build_object('id',customer_id,'name',company_name)),'[]') from public.customers where customer_id=(r->'header'->>'customer_id')::bigint),'currencies',(select coalesce(jsonb_agg(jsonb_build_object('id',currency_id,'code',currency_code)),'[]') from public.currencies where currency_id=(r->'header'->>'currency_id')::bigint),'locations',(select coalesce(jsonb_agg(jsonb_build_object('id',location_id,'name',name)),'[]') from public.locations where location_id=(r->'header'->>'location_id')::bigint),'sources',(select coalesce(jsonb_agg(jsonb_build_object('id',document_id,'number',document_number)),'[]') from public.sales_document where document_id=(r->'header'->>'source_document_id')::bigint and subsidiary_id=sid),'products',(select coalesce(jsonb_agg(jsonb_build_object('id',p.product_id,'code',p.item_code,'name',p.display_name)),'[]') from public.products p where exists(select 1 from public.sales_document_line l where l.document_id=id and l.product_id=p.product_id))));end$$;
create function public.sales_document_detail(p_document_id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform sales_workflow_private.header(p_document_id,'view');return sales_workflow_private.detail(p_document_id);end$$;
create function public.sales_document_edit_context(p_document_id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.sales_document;begin d:=sales_workflow_private.header(p_document_id,'edit');d:=sales_workflow_private.lock_header(p_document_id);perform sales_workflow_private.editable(d);return sales_workflow_private.detail(p_document_id);end$$;
create function public.sales_document_source(p_document_id bigint,p_type text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r jsonb;lines jsonb;begin perform sales_workflow_private.source(p_document_id,p_type);r:=sales_workflow_private.detail(p_document_id);
 select coalesce(jsonb_agg(to_jsonb(l)||jsonb_build_object('quantity',x.available) order by l.line_number),'[]') into lines from public.sales_document_line l cross join lateral(select greatest(l.quantity-coalesce((select sum(cl.quantity) from public.sales_document child join public.sales_document_line cl on cl.document_id=child.document_id where child.source_document_id=p_document_id and child.document_type=p_type and child.status<>'CANCELADO' and(cl.source_line_id=l.line_id or(cl.source_line_id is null and cl.line_number=l.line_number))),0),0) available)x where l.document_id=p_document_id and x.available>.000001;
 if lines='[]'::jsonb then raise exception using errcode='55000',message='El origen no tiene cantidades pendientes.';end if;return r||jsonb_build_object('lines',lines);end$$;
create function public.delete_sales_document(p_document_id bigint) returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.sales_document;begin d:=sales_workflow_private.header(p_document_id,'delete');d:=sales_workflow_private.lock_header(p_document_id);perform sales_workflow_private.editable(d);if exists(select 1 from public.wf_instances where entity_type='SALES_ORDER' and entity_id=p_document_id) then raise exception using errcode='55000',message='La orden conserva su historial de aprobación.';end if;return sales_workflow_private.delete_sales_document(p_document_id);end$$;
create function public.sales_workflow_context(p_type text) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare ctx jsonb:=public.sales_document_access(p_type);r jsonb;sid bigint:=asset_posting_private.identity();begin
 r:=sales_workflow_private.sales_workflow_options();if not((ctx->>'canCreate')::boolean or(ctx->>'canEdit')::boolean) then return jsonb_build_object('access',ctx,'subsidiary',r->'subsidiary');end if;
 return r||jsonb_build_object('access',ctx,'sources',(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(r->'sources')x join public.sales_document s on s.document_id=(x->>'id')::bigint where s.subsidiary_id=sid and s.document_type=case p_type when 'ORDER' then 'QUOTE' when 'DELIVERY' then 'ORDER' end and(p_type<>'DELIVERY' or s.status='APROBADO')),'periods',(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(r->'periods')x join public.fiscal_periods f on f.fiscal_period_id=(x->>'id')::bigint where not coalesce(f.gl_closed,false) and not coalesce(f.is_inactive,false)),'taxes',(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(r->'taxes')x join public.tax_codes tc on tc.tax_code_id=(x->>'id')::bigint join public.tax_types tt using(tax_type_id) where not tc.is_withholding and tt.applies_to in('Ventas','Ambos')));end$$;
create function public.sales_workflow_options() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare k text;begin foreach k in array array['QUOTE','ORDER','DELIVERY'] loop if sales_workflow_private.allowed(k,'create') or sales_workflow_private.allowed(k,'edit') then return public.sales_workflow_context(k);end if;end loop;raise exception using errcode='42501',message='Use las opciones del tipo autorizado.';end$$;
alter function sales_workflow_private.save_sales_document(jsonb,bigint) set search_path=pg_catalog,public,pg_temp;
alter function sales_workflow_private.delete_sales_document(bigint) set search_path=pg_catalog,public,pg_temp;
alter function sales_workflow_private.sales_document_detail(bigint) set search_path=pg_catalog,public,pg_temp;
alter function sales_workflow_private.sales_document_report(jsonb) set search_path=pg_catalog,public,pg_temp;
alter function sales_workflow_private.sales_workflow_options() set search_path=pg_catalog,public,pg_temp;
create function sales_workflow_private.fingerprint(id bigint) returns text language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select md5(jsonb_build_object('header',jsonb_build_array(d.document_id,d.document_type,d.document_number,d.document_date,d.valid_until,d.customer_id,d.subsidiary_id,d.currency_id,d.exchange_rate,d.fiscal_period_id,d.location_id,d.payment_term_id,d.source_document_id,d.memo,d.total_amount,d.transaction_id),'lines',(select jsonb_agg(jsonb_build_array(l.line_id,l.document_id,l.line_number,l.product_id,l.account_id,l.description,l.quantity,l.unit_price,l.tax_code_id,l.tax_rate,l.tax_amount,l.gross_amount,l.department_id,l.cost_center_id,l.class_id,l.related_company_id,l.source_line_id) order by line_number) from public.sales_document_line l where l.document_id=$1))::text) from public.sales_document d where document_id=$1$$;
create function sales_workflow_private.submit_access(id bigint) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.sales_document;p jsonb;begin
 d:=sales_workflow_private.header(id,'edit');if d.document_type<>'ORDER' then raise exception using errcode='42501',message='Orden no disponible.';end if;perform sales_workflow_private.editable(d);
 p:=jsonb_build_object('type','ORDER','date',d.document_date,'customer_id',d.customer_id,'currency_id',d.currency_id,'rate',d.exchange_rate,'period_id',d.fiscal_period_id,'location_id',d.location_id,'payment_term_id',d.payment_term_id,'source_id',d.source_document_id,'status','BORRADOR','lines',(select jsonb_agg(to_jsonb(l) order by line_number) from public.sales_document_line l where l.document_id=id));
 perform sales_workflow_private.prepare(p,id);if not asset_posting_private.finite(d.total_amount) or d.total_amount<=0 or d.total_amount is distinct from(select sum(gross_amount) from public.sales_document_line where document_id=id) then raise exception using errcode='55000',message='Importe de orden inconsistente.';end if;end$$;
create function sales_workflow_private.submit_engine(id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r jsonb;prior text:=current_setting('nexo.sales_order_id',true);begin
 perform sales_workflow_private.submit_access(id);perform set_config('nexo.sales_order_id',id::text,true);
 r:=payment_request_private.wf_start_entity_without_budget('SALES_ORDER',id,jsonb_build_object('orderFingerprint',sales_workflow_private.fingerprint(id)));
 if not exists(select 1 from public.wf_instance_steps where instance_id=(r->>'id')::bigint) then raise exception using errcode='55000',message='La orden requiere un nivel de aprobación aplicable.';end if;
 perform set_config('nexo.sales_order_id',coalesce(prior,''),true);return r;end$$;
do $$declare body text;modified text;begin body:=pg_get_functiondef('public.budget_run(text,jsonb,bigint)'::regprocedure);
 modified:=replace(body,'begin'||chr(10),'begin'||chr(10)||' if p_type=''WORKFLOW_START'' and p_payload->>''entityType''=''SALES_ORDER'' then perform sales_workflow_private.submit_access(p_id);p_payload:=jsonb_build_object(''entityType'',''SALES_ORDER'',''context'',jsonb_build_object(''orderFingerprint'',sales_workflow_private.fingerprint(p_id)));end if;'||chr(10));
 modified:=replace(modified,'else result:=wf_start_entity_without_budget(p_payload->>''entityType'',p_id,coalesce(p_payload->''context'',''{}''));','elsif p_payload->>''entityType''=''SALES_ORDER'' then result:=sales_workflow_private.submit_engine(p_id);else result:=wf_start_entity_without_budget(p_payload->>''entityType'',p_id,coalesce(p_payload->''context'',''{}''));');
 if position('sales_workflow_private.submit_engine(p_id)' in modified)=0 then raise exception 'Unexpected sales approval dispatcher';end if;execute modified;
end$$;
alter function public.wf_act(bigint,text,text,inet) set schema sales_workflow_private;
alter function public.wf_instance_detail(text,bigint) set schema sales_workflow_private;
create function public.wf_act(p_instance_id bigint,p_action text,p_comment text default null,p_ip inet default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare i public.wf_instances;d public.sales_document;prior text:=current_setting('nexo.sales_order_id',true);r jsonb;begin
 perform asset_posting_private.identity();select * into i from public.wf_instances where id=p_instance_id for update;
 if i.entity_type='SALES_ORDER' then
 d:=sales_workflow_private.header(i.entity_id,case upper(p_action) when 'CANCELAR' then 'delete' else 'view' end);d:=sales_workflow_private.lock_header(d.document_id);
 if d.document_type<>'ORDER' or i.subsidiaria_id<>d.subsidiary_id or i.status<>'EN_REVISION' or d.status<>'PENDIENTE_APROBACION' or i.amount is distinct from d.total_amount or i.approval_context->>'orderFingerprint' is distinct from sales_workflow_private.fingerprint(d.document_id) then raise exception using errcode='55000',message='Orden o aprobación protegida por estado o importe.';end if;
 if upper(p_action) in('APROBAR','RECHAZAR') and not exists(select 1 from public.wf_instance_steps s where s.instance_id=i.id and s.nivel=i.current_level and s.status='PENDIENTE' and(s.usuario_aprobador_id=public.app_user_id() or s.rol_aprobador_id=public.app_active_role_id())) then raise exception using errcode='42501',message='El rol activo no está asignado a este nivel.';end if;
 if upper(p_action) in('RECHAZAR','CANCELAR') and nullif(trim(p_comment),'') is null then raise exception using errcode='22023',message='Indique el motivo.';end if;perform set_config('nexo.sales_order_id',d.document_id::text,true);
 end if;
 r:=sales_workflow_private.wf_act(p_instance_id,p_action,p_comment,p_ip);perform set_config('nexo.sales_order_id',coalesce(prior,''),true);return r;end$$;
create function public.wf_instance_detail(p_entity_type text,p_entity_id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_entity_type='SALES_ORDER' and not sales_workflow_private.visible(p_entity_id) then raise exception using errcode='42501',message='Orden no disponible.';end if;return sales_workflow_private.wf_instance_detail(p_entity_type,p_entity_id);end$$;
do $$declare f regprocedure;body text;begin foreach f in array array['public.wf_start_entity_without_budget(text,bigint,jsonb)'::regprocedure,'public.wf_apply_entity_status(text,bigint,text)'::regprocedure,'public.wf_apply_entity_status_without_budget(text,bigint,text)'::regprocedure] loop body:=pg_get_functiondef(f);body:=replace(body,'begin','begin if '||case when f::text like '%wf_start_entity%' then 'p_entity_type' else 'p_type' end||'=''SALES_ORDER'' then raise exception using errcode=''42501'',message=''Use el flujo protegido de ventas.'';end if;');execute body;end loop;end$$;
create function sales_workflow_private.header_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin
 if old.document_type='DELIVERY' then raise exception using errcode='55000',message='El despacho registrado conserva su historial.';end if;
 if tg_op='DELETE' then if exists(select 1 from public.sales_document where source_document_id=old.document_id) or exists(select 1 from public.wf_instances where entity_type='SALES_ORDER' and entity_id=old.document_id) then raise exception using errcode='55000',message='El documento tiene historial relacionado.';end if;return old;end if;
 if new.document_type is distinct from old.document_type then raise exception using errcode='42501',message='Tipo de documento inmutable.';end if;
 if old.document_type='ORDER' then
 if new.status is distinct from old.status and current_setting('nexo.sales_order_id',true) is distinct from old.document_id::text and not(current_setting('nexo.sales_delivery_write',true)='true' and old.status in('BORRADOR','RECHAZADO') and new.status='BORRADOR') then raise exception using errcode='42501',message='Estado reservado al flujo de aprobación.';end if;
 if old.status not in('BORRADOR','RECHAZADO') and(to_jsonb(new)-array['status','updated_at','updated_by_id','updated_by_email','updated_by_name','updated_actor_type','updated_actor_source','updated_execution_context_id'])<>(to_jsonb(old)-array['status','updated_at','updated_by_id','updated_by_email','updated_by_name','updated_actor_type','updated_actor_source','updated_execution_context_id']) then raise exception using errcode='55000',message='La orden en aprobación conserva sus términos.';end if;
 end if;return new;end$$;
create trigger sales_document_history_guard before update or delete on public.sales_document for each row execute function sales_workflow_private.header_guard();
create function sales_workflow_private.line_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.sales_document;begin select * into d from public.sales_document where document_id=old.document_id;
 if d.document_type='DELIVERY' or d.status not in('BORRADOR','RECHAZADO') or exists(select 1 from public.sales_document where source_document_id=d.document_id) then
 if not(tg_op='UPDATE' and current_setting('nexo.sales_delivery_write',true)='true' and old.source_line_id is null and(to_jsonb(new)-'source_line_id')=(to_jsonb(old)-'source_line_id') and not exists(select 1 from public.wf_instances where entity_type='SALES_ORDER' and entity_id=d.document_id)) then raise exception using errcode='55000',message='Las líneas conservan aprobación y movimientos posteriores.';end if;
 end if;return case when tg_op='DELETE' then old else new end;end$$;
create trigger sales_document_line_history_guard before update or delete on public.sales_document_line for each row execute function sales_workflow_private.line_guard();
-- Invoice creation is an explicit, one-time transition, never inferred from memo text.
create or replace function public.link_invoice_to_sales_delivery() returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin
 if tg_op='UPDATE' and old.sales_delivery_document_id is not null and row(new.sales_delivery_document_id,new.subsidiary_id,new.customer_id,new.currency_id,new.location_id) is distinct from row(old.sales_delivery_document_id,old.subsidiary_id,old.customer_id,old.currency_id,old.location_id) then raise exception using errcode='55000',message='La factura conserva su despacho de origen.';end if;
 if new.sales_delivery_document_id is not null and(tg_op='INSERT' or new.sales_delivery_document_id is distinct from old.sales_delivery_document_id) and(current_setting('nexo.sales_delivery_invoice',true) is distinct from new.sales_delivery_document_id::text or not exists(select 1 from public.sales_document d where d.document_id=new.sales_delivery_document_id and d.document_type='DELIVERY' and d.subsidiary_id=new.subsidiary_id and d.customer_id=new.customer_id and d.currency_id=new.currency_id)) then raise exception using errcode='42501',message='Vínculo de despacho no autorizado.';end if;return new;end$$;
create function sales_workflow_private.invoice_source(id bigint) returns public.sales_document language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.sales_document;begin d:=sales_workflow_private.source(id,'INVOICE');
 if (select count(*) from public.stock_movements where transaction_id=d.transaction_id)<>(select count(*) from public.sales_document_line where document_id=id) or exists(select 1 from public.sales_document_line l where l.document_id=id and not exists(select 1 from public.stock_movements m where m.sales_delivery_line_id=l.line_id and m.transaction_id=d.transaction_id and m.product_id=l.product_id and m.quantity=-l.quantity and m.location_id=d.location_id)) then raise exception using errcode='55000',message='El despacho requiere revisión de sus movimientos.';end if;return d;end$$;
create function public.sales_delivery_invoice_source(p_delivery_id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.sales_document;begin d:=sales_workflow_private.invoice_source(p_delivery_id);return sales_workflow_private.detail(p_delivery_id)||jsonb_build_object('countryId',(select country_id from public.subsidiaries where subsidiary_id=d.subsidiary_id));end$$;
do $$declare body text;needle text:='select l.location_id into loc from locations l join location_subsidiaries s using(location_id) where s.subsidiary_id=sid order by l.name limit 1;';begin
 body:=pg_get_functiondef('sales_invoice_private.save_sales_invoice_without_withholding(jsonb,bigint)'::regprocedure);
 if position(needle in body)=0 then raise exception 'Unexpected sales invoice location reader';end if;
 execute replace(body,needle,'if nullif(payload->>''location_id'','''') is not null then loc:=(payload->>''location_id'')::bigint;else '||needle||'end if;');end$$;
create function public.save_sales_invoice_from_delivery(p_delivery_id bigint,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.sales_document;p jsonb;r jsonb;i public.invoice;l public.sales_document_line;ln jsonb;idx int:=0;debit numeric;credit numeric;prior text:=current_setting('nexo.sales_delivery_invoice',true);begin
 d:=sales_workflow_private.invoice_source(p_delivery_id);p:=sales_invoice_private.prepare(p_payload,null);
 if(d.customer_id is distinct from(p->>'customer_id')::bigint or d.currency_id is distinct from(p->>'currency_id')::bigint or d.payment_term_id is distinct from(p->>'payment_term_id')::bigint or(p->>'invoice_date')::date<d.document_date) or jsonb_array_length(p->'lines')<>(select count(*) from public.sales_document_line where document_id=d.document_id) then raise exception using errcode='42501',message='La factura debe conservar el despacho de origen.';end if;
 for ln in select value from jsonb_array_elements(p->'lines') loop idx:=idx+1;select * into l from public.sales_document_line where document_id=d.document_id and line_number=idx;
 if l.product_id is distinct from(ln->>'product_id')::bigint or l.quantity is distinct from(ln->>'quantity')::numeric or l.unit_price is distinct from(ln->>'unit_price')::numeric or l.tax_code_id is distinct from nullif(ln->>'tax_code_id','')::bigint or l.tax_rate is distinct from(ln->>'tax_rate')::numeric or l.department_id is distinct from nullif(ln->>'department_id','')::bigint or l.cost_center_id is distinct from nullif(ln->>'cost_center_id','')::bigint or l.class_id is distinct from nullif(ln->>'class_id','')::bigint or l.related_company_id is distinct from nullif(ln->>'related_company_id','')::bigint then raise exception using errcode='42501',message='Las líneas deben conservar el despacho.';end if;end loop;
 if not inventory_balance_private.location(d.location_id) then raise exception using errcode='42501',message='Ubicación del despacho no disponible.';end if;
 perform set_config('nexo.sales_delivery_invoice',d.document_id::text,true);r:=sales_invoice_private.save_sales_invoice((p-'supports')||jsonb_build_object('location_id',d.location_id),null);
 select * into i from public.invoice where invoice_id=(r->>'invoiceId')::bigint and subsidiary_id=d.subsidiary_id;
 if not found or i.location_id is distinct from d.location_id then raise exception using errcode='55000',message='La factura no conserva su ubicación de origen.';end if;
 update public.invoice set sales_delivery_document_id=d.document_id where invoice_id=i.invoice_id;
 select sum(debit_amount),sum(credit_amount) into debit,credit from public.gl_impact where transaction_id=i.transaction_id;
 if not asset_posting_private.finite(debit) or not asset_posting_private.finite(credit) or debit<=0 or abs(debit-credit)>.000001 then raise exception using errcode='55000',message='La factura no produjo mayor balanceado.';end if;
 if p_payload?'supports' then perform sales_invoice_private.supports(i.journal_id,p_payload->'supports');end if;perform set_config('nexo.sales_delivery_invoice',coalesce(prior,''),true);return r;end$$;
-- Unified tables and legacy catalog boundaries.
do $$declare t text;p record;c record;begin foreach t in array array['sales_document','sales_document_line','quotation','sales_order','delivery'] loop
 execute format('alter table public.%I enable row level security',t);for p in select policyname from pg_policies where schemaname='public' and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 for c in select column_name from information_schema.columns where table_schema='public' and table_name=t loop execute format('revoke all (%I) on public.%I from public,anon,authenticated,service_role',c.column_name,t);end loop;execute format('grant select on public.%I to authenticated',t);end loop;end$$;
create policy sales_document_read on public.sales_document for select to authenticated using(sales_workflow_private.visible(document_id));
create policy sales_document_line_read on public.sales_document_line for select to authenticated using(sales_workflow_private.visible(document_id));
create policy sales_quotation_read on public.quotation for select to authenticated using(subsidiary_id=asset_posting_private.identity() and sales_workflow_private.allowed('QUOTE','view'));
create policy sales_order_legacy_read on public.sales_order for select to authenticated using(subsidiary_id=asset_posting_private.identity() and sales_workflow_private.allowed('ORDER','view'));
create policy sales_delivery_legacy_read on public.delivery for select to authenticated using(sales_workflow_private.allowed('DELIVERY','view') and exists(select 1 from public."transaction" t where t.transaction_id=delivery.transaction_id and t.subsidiary_id=asset_posting_private.identity()));
create function sales_workflow_private.transaction_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.sales_document;begin select * into d from public.sales_document where transaction_id=old.transaction_id;
 if not found then return case when tg_op='DELETE' then old else new end;end if;
 if tg_op='DELETE' then raise exception using errcode='55000',message='Use el proceso protegido del documento de venta.';end if;
 if row(new.tran_number,new.tran_date,new.transaction_type_id,new.subsidiary_id,new.currency_id,new.exchange_rate,new.fiscal_period_id,new.total_amount,new.status_id,new.customer_id,new.payment_term_id) is distinct from row(old.tran_number,old.tran_date,old.transaction_type_id,old.subsidiary_id,old.currency_id,old.exchange_rate,old.fiscal_period_id,old.total_amount,old.status_id,old.customer_id,old.payment_term_id)
 and(d.document_type='DELIVERY' or d.status not in('BORRADOR','RECHAZADO') or current_setting('nexo.sales_delivery_write',true) is distinct from 'true') then raise exception using errcode='55000',message='La transacción conserva aprobación y movimientos de venta.';end if;return new;end$$;
create trigger sales_document_transaction_history before update or delete on public."transaction" for each row execute function sales_workflow_private.transaction_guard();
do $$declare body text;begin body:=pg_get_functiondef('purchase_receipt_private.stock_visible(bigint,bigint)'::regprocedure);
 if position('or (purchase_order_private.allowed(' in body)=0 then raise exception 'Unexpected stock visibility helper';end if;
 execute replace(body,'or (purchase_order_private.allowed(', 'or (sales_workflow_private.allowed(''DELIVERY'',''view'') and exists(select 1 from public.sales_document d where d.transaction_id=tid and d.document_type=''DELIVERY'' and d.subsidiary_id=sid and d.location_id=loc)) or (purchase_order_private.allowed(');
end$$;
revoke all on all functions in schema sales_workflow_private from public,anon,authenticated,service_role;
grant execute on function sales_workflow_private.visible(bigint),sales_workflow_private.allowed(text,text) to authenticated;
revoke all on function public.link_invoice_to_sales_delivery(),public.wf_protect_sales_order() from public,anon,authenticated,service_role;
revoke all on function public.save_sales_document(jsonb,bigint) from public,anon,authenticated,service_role;grant execute on function public.save_sales_document(jsonb,bigint) to authenticated;
revoke all on function public.delete_sales_document(bigint) from public,anon,authenticated,service_role;grant execute on function public.delete_sales_document(bigint) to authenticated;
revoke all on function public.sales_document_detail(bigint) from public,anon,authenticated,service_role;grant execute on function public.sales_document_detail(bigint) to authenticated;
