notify pgrst,'reload schema';

-- Preserve the existing purchase/payment inbox restrictions; scope sales to the active role.
DO $inbox$
declare definition text; needle text := 'and i.subsidiaria_id=active_subsidiary_id()';
begin
 definition:=pg_get_functiondef('public.wf_inbox()'::regprocedure);
 if strpos(definition,needle)=0 then raise exception 'Unexpected inbox definition'; end if;
 definition:=replace(definition,needle,'and (i.entity_type<>''SALES_ORDER'' or (sales_workflow_private.visible(i.entity_id) and (s.usuario_aprobador_id=public.app_user_id() or s.rol_aprobador_id=public.app_active_role_id()))) '||needle);
 execute definition;
end $inbox$;
